// ============ 一样的代码，不一样的含义 ============
//
// 这个函数和 03-01 里的 NewNode 一模一样，不多解释。
// 要说的是**它在 BST 里的位置**：新结点永远是被"挂到某个空位置上"的，
// 挂上去之后它就成了叶子 —— BST 的插入从不改动已有结点之间的关系。

// 造一个值为 x 的孤立结点
BinTree NewNode(ElemType x)
{
// 申请内存
    BinTree t = (BinTree)malloc(sizeof(TNode));
// 挡住分配失败
    if (t == NULL)
    {
        printf("内存分配失败\n");
        exit(1);
    }
// 填值
    t->data = x;
// 两个孩子置空 —— 新结点一定是叶子
    t->left = NULL;
    t->right = NULL;
// 返回
    return t;
}

