// ============ 查找的路径 ============
//
// 在以 8 为根的 BST 里找 7：
//
//          8         7 < 8  → 往左
//        /   \
//       3     10     7 > 3  → 往右
//      / \      \
//     1   6      14  7 > 6  → 往右
//        / \    /
//       4   7  13    相等！找到了
//
// 一共比较了 4 次。如果这是有序数组用二分，也要 log 次 ——
// **BST 的查找本质就是"写成树的二分查找"**。
//
// ============ 递归还是循环 ============
//
// 递归写起来最贴题意（三行），缺点是树很深时会消耗调用栈。
// 这里两个版本都给：递归看思路，循环看工程。
// 循环版其实更好 —— 尾递归本来就能直接改成 while。

// 递归版：返回找到的结点，找不到返回 NULL
BinTree BSTFind(BinTree T, ElemType x)
{
// 走到空说明整棵树都找遍了，没有
    if (T == NULL)
    {
        return NULL;
    }

// 目标更小 → 只可能在左子树
    if (x < T->data)
    {
        return BSTFind(T->left, x);
    }
// 目标更大 → 只可能在右子树
    if (x > T->data)
    {
        return BSTFind(T->right, x);
    }

// 相等 —— 命中，返回这个结点
// 返回结点地址而不是 1/0，是因为调用者往往还要用到它（比如接着删除、
// 或者读它的其他字段）。
    return T;
}

// 循环版：功能相同，但不占调用栈
// 尾递归可以直接改写成循环 —— 这是在工程代码里更常见的写法。
BinTree BSTFindIter(BinTree T, ElemType x)
{
// 一路往下走，直到走到空或者命中
    while (T != NULL && T->data != x)
    {
// 比当前小就往左，否则往右 —— 一次比较决定一半的去留
        T = (x < T->data) ? T->left : T->right;
    }
// 循环结束时 T 要么是要找的结点，要么是 NULL
    return T;
}

