    printf("查 5  → %s\n", BSTFind(T, 5) ? "找到" : "没找到（5 确实没插进去）");

    /* 递归版与循环版结果必须一致 */
    printf("\n两版一致性检查：\n");
    printf("  找 7 : 递归 %s，循环 %s\n",
           BSTFind(T, 7) ? "有" : "无", BSTFindIter(T, 7) ? "有" : "无");
    printf("  找 5 : 递归 %s，循环 %s\n",
           BSTFind(T, 5) ? "有" : "无", BSTFindIter(T, 5) ? "有" : "无");
    printf("（递归看思路，循环看工程 —— 尾递归都能这样改）\n");

    FreeTree(T);
    return 0;
}

