modes.detail:
// ============ 三种情况 ============
//
// **情况一：要删的是叶子**（没有孩子）
//
//       ... 6               ... 6
//          / \      →         /
//         4   7              4        直接拿掉 7，什么都不用管
//
// **情况二：只有一个孩子**
//
//       14                13
//      /         →       /         拿孩子顶替自己的位置
//    13                 11
//   /
//  11
//
// **情况三：有两个孩子** —— 麻烦在这里
//
//          8                    10
//        /   \                /    \
//       3     10     →       3      14
//      / \      \           / \    /
//     1   6      14         1   6  13
//                                     ← 13 还在，位置没变
//
// 删 8 不能直接把 8 拿掉 —— 那样左右两棵子树就没法拼成一棵树了。
// 办法是**找个替身**：用右子树里最小的那个（10）的值覆盖 8，
// 然后再去右子树里把那个"10 号结点"删掉（它最多只有一个孩子，好删）。
//
// ============ 为什么替身是"右子树最小值" ============
//
// 因为它比右子树里所有结点都小、又比左子树里所有结点都大 ——
// 放在根的位置正好满足 BST 的规矩。
// 换成左子树的最大值也可以，对称的。
//
// ============ 写这段代码的关键 ============
//
// 一定要**先递归、再把返回值接回去**：
//
//     T->left = BSTDelete(T->left, x);
//
// 因为删掉左子树的根之后，左子树的根可能换人了，必须重新接上。
// 漏掉这个赋值是这一节最常见的 bug。

// 删除值为 x 的结点，返回新的树根
// 同样要接收返回值：T = BSTDelete(T, x);
BinTree BSTDelete(BinTree T, ElemType x)
{
// 被删结点
    BinTree tmp;

// 走到空也没找到 —— 什么也不做
    if (T == NULL)
    {
        return NULL;
    }

// 还没找到：继续往左
    if (x < T->data)
    {
// 这一句的赋值千万不能省。删完之后左子树的根可能变了，必须接回来。
        T->left = BSTDelete(T->left, x);
    }
// 继续往右
    else if (x > T->data)
    {
        T->right = BSTDelete(T->right, x);
    }
// 找到了，就是当前这个结点
    else
    {
// 情况三：两个孩子都在
        if (T->left != NULL && T->right != NULL)
        {
// 找右子树里的最小值当替身
            tmp = FindMin(T->right);
// 用替身的值覆盖自己
// 只改值不改结构 —— 这是最省事的做法（如果结点里还有别的数据，
// 别忘了也一起搬过来）。
            T->data = tmp->data;
// 再去右子树里把那个替身结点删掉
// 它能走到这里，说明它一定没有左孩子（一路向左走到底的），
// 所以下一轮递归最多只有一个孩子，问题规模缩小了。
            T->right = BSTDelete(T->right, tmp->data);
        }
// 情况一 / 二：至多一个孩子
        else
        {
// 先记住要被 free 的结点
            tmp = T;
// 让唯一的孩子（或者 NULL）顶替上来
// 左孩子存在就用左孩子，否则用右孩子。两个都没有时
// 表达式的结果正好是 NULL —— 一个式子覆盖了两种情况。
            T = (T->left != NULL) ? T->left : T->right;
// 释放被删结点
            free(tmp);
        }
    }

// 返回（可能已经换人的）根
    return T;
}

