// 反过来，如果哪里乱了序，说明删除或插入写错了。
//
// 比"盯着树看"可靠得多 —— 树一深，人是看不出问题的。

// 主函数
int main(void)
{
// 树根，空树从 NULL 开始
    BinTree T = NULL;
// 插入序列
// 故意选一个"顺序有点乱"的序列，这样建出来的树两边都长，不会退化成链。
    static const int ins[] = { 8, 3, 10, 1, 6, 14, 4, 7, 13 };
// 计数
    int i;
// 查找结果
    BinTree found;

// 逐个插入
    for (i = 0; i < (int)(sizeof(ins) / sizeof(ins[0])); i++)
    {
        T = BSTInsert(T, ins[i]);
    }

// 用中序验证：必须递增
    printf("插入 %d 个值后，中序遍历: ", (int)(sizeof(ins) / sizeof(ins[0])));
    InOrder(T);
    printf("\n（BST 的中序一定递增 —— 只要有序就说明结构是对的）\n\n");

// 查找命中
    found = BSTFind(T, 7);
    printf("查 7  → %s\n", found ? "找到" : "没找到");
// 查找未命中
    found = BSTFind(T, 99);
    printf("查 99 → %s\n", found ? "找到" : "没找到（BST 里没有）");

// 找最值
    printf("最小值 = %d，最大值 = %d\n\n", FindMin(T)->data, FindMax(T)->data);

// 情况一：删叶子
    T = BSTDelete(T, 7);
    printf("删 7 （叶子）     : ");
    InOrder(T);
    printf("\n");

// 情况二：删只有一个孩子的结点（13 只有左孩子 11？这里删 1 是叶子）
// 为了演示情况二，15 是挂在 14 右边的单孩子结点。
    T = BSTInsert(T, 15);
    T = BSTDelete(T, 14);
    printf("删 14（一个孩子） : ");
    InOrder(T);
    printf("\n");

// 情况三：删有两个孩子的结点
    T = BSTDelete(T, 3);
    printf("删 3 （两个孩子） : ");
    InOrder(T);
    printf("\n");

// 删根
    T = BSTDelete(T, 8);
    printf("删 8 （树根）     : ");
    InOrder(T);
    printf("\n");

// 删一个不存在的值：应该什么都不做
    T = BSTDelete(T, 999);
    printf("删 999（不存在）  : ");
    InOrder(T);
    printf("\n（什么都没变 —— 删除不存在的值不应该破坏结构）\n");

// 释放
    FreeTree(T);
// 正常结束
    return 0;
}

