    if (t == NULL)
    {
        printf("内存分配失败\n");
        exit(1);
    }
    t->data = x;
    t->left = NULL;
    t->right = NULL;
    return t;
}

/* ======== [已给出] 模块 03 BSTFind ======== */

BinTree BSTFind(BinTree T, ElemType x)
{
    if (T == NULL)
    {
        return NULL;
    }

    if (x < T->data)
    {
        return BSTFind(T->left, x);
    }
    if (x > T->data)
    {
        return BSTFind(T->right, x);
    }

    return T;
}

BinTree BSTFindIter(BinTree T, ElemType x)
{
    while (T != NULL && T->data != x)
    {
        T = (x < T->data) ? T->left : T->right;
    }
    return T;
}

/* ======== [已给出] 模块 04 BSTInsert ======== */

BinTree BSTInsert(BinTree T, ElemType x)
{
    if (T == NULL)
    {
        return NewNode(x);
    }

    if (x < T->data)
    {
        T->left = BSTInsert(T->left, x);
    }
    else if (x > T->data)
    {
        T->right = BSTInsert(T->right, x);
    }

    return T;
}

/* ======== [已给出] 模块 05 FindMin ======== */

BinTree FindMin(BinTree T)
{
    if (T == NULL)
    {
        return NULL;
    }
    while (T->left != NULL)
    {
        T = T->left;
    }
    return T;
}

BinTree FindMax(BinTree T)
{
    if (T == NULL)
    {
        return NULL;
    }
    while (T->right != NULL)
    {
        T = T->right;
    }
    return T;
}

/* ======== [已给出] 模块 06 BSTDelete ======== */

BinTree BSTDelete(BinTree T, ElemType x)
{
    BinTree tmp;

    if (T == NULL)
    {
        return NULL;
    }

    if (x < T->data)
    {
        T->left = BSTDelete(T->left, x);
    }
    else if (x > T->data)
    {
        T->right = BSTDelete(T->right, x);
    }
    else
    {
        if (T->left != NULL && T->right != NULL)
        {
            tmp = FindMin(T->right);
            T->data = tmp->data;
            T->right = BSTDelete(T->right, tmp->data);
        }
        else
        {
            tmp = T;
            T = (T->left != NULL) ? T->left : T->right;
            free(tmp);
        }
    }

    return T;
}

/* ======== [已给出] 模块 07 InOrder ======== */

