#include <stdio.h>
#include <stdlib.h>


// 数据元素类型
typedef int ElemType;

// 结点结构：和普通二叉树完全一样
typedef struct TNode
{
// 数据域
    ElemType data;
// 左子树（都比它小）
    struct TNode *left;
// 右子树（都比它大）
    struct TNode *right;
} TNode, *BinTree;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;


// 造一个值为 x 的孤立结点
BinTree NewNode(ElemType x)
{
// 申请内存
    BinTree t = (BinTree)malloc(sizeof(TNode));
// 挡住分配失败
    if (t == NULL)
    {
        printf("内存分配失败\n");
        exit(1);
    }
// 填值
    t->data = x;
// 两个孩子置空 —— 新结点一定是叶子
    t->left = NULL;
    t->right = NULL;
// 返回
    return t;
}


// 递归版：返回找到的结点，找不到返回 NULL
BinTree BSTFind(BinTree T, ElemType x)
{
// 走到空说明整棵树都找遍了，没有
    if (T == NULL)
    {
        return NULL;
    }

// 目标更小 → 只可能在左子树
    if (x < T->data)
    {
        return BSTFind(T->left, x);
    }
// 目标更大 → 只可能在右子树
    if (x > T->data)
    {
        return BSTFind(T->right, x);
    }

// 相等 —— 命中，返回这个结点
    return T;
}

// 循环版：功能相同，但不占调用栈
BinTree BSTFindIter(BinTree T, ElemType x)
{
// 一路往下走，直到走到空或者命中
    while (T != NULL && T->data != x)
    {
// 比当前小就往左，否则往右 —— 一次比较决定一半的去留
        T = (x < T->data) ? T->left : T->right;
    }
// 循环结束时 T 要么是要找的结点，要么是 NULL
    return T;
}


// 插入 x，返回新的树根
BinTree BSTInsert(BinTree T, ElemType x)
{
// 走到空位置 → 这就是新结点该待的地方
    if (T == NULL)
    {
        return NewNode(x);
    }

// 比当前小 → 递归插到左子树，并把结果接回左指针
    if (x < T->data)
    {
        T->left = BSTInsert(T->left, x);
    }
// 比当前大 → 插到右子树
    else if (x > T->data)
    {
        T->right = BSTInsert(T->right, x);
    }
// 相等 → 已经存在，什么也不做（也可以改成计数）

// 返回（可能被修改过的）根
    return T;
}


// 返回最小结点；空树返回 NULL
BinTree FindMin(BinTree T)
{
// 空树直接返回
    if (T == NULL)
    {
        return NULL;
    }
// 一路往左，直到没有左孩子
    while (T->left != NULL)
    {
        T = T->left;
    }
// 停下来时 T 就是最小结点
    return T;
}

// 返回最大结点；空树返回 NULL
BinTree FindMax(BinTree T)
{
// 空树
    if (T == NULL)
    {
        return NULL;
    }
// 一路往右
    while (T->right != NULL)
    {
        T = T->right;
    }
// 停下来的就是最大
    return T;
}


// 删除值为 x 的结点，返回新的树根
BinTree BSTDelete(BinTree T, ElemType x)
{
// 被删结点
    BinTree tmp;

// 走到空也没找到 —— 什么也不做
    if (T == NULL)
    {
        return NULL;
    }

// 还没找到：继续往左
    if (x < T->data)
    {
        T->left = BSTDelete(T->left, x);
    }
// 继续往右
    else if (x > T->data)
    {
        T->right = BSTDelete(T->right, x);
    }
// 找到了，就是当前这个结点
    else
    {
// 情况三：两个孩子都在
        if (T->left != NULL && T->right != NULL)
        {
// 找右子树里的最小值当替身
            tmp = FindMin(T->right);
// 用替身的值覆盖自己
            T->data = tmp->data;
// 再去右子树里把那个替身结点删掉
            T->right = BSTDelete(T->right, tmp->data);
        }
// 情况一 / 二：至多一个孩子
        else
        {
// 先记住要被 free 的结点
            tmp = T;
// 让唯一的孩子（或者 NULL）顶替上来
            T = (T->left != NULL) ? T->left : T->right;
// 释放被删结点
            free(tmp);
        }
    }

// 返回（可能已经换人的）根
    return T;
}


// 中序遍历（把 BST 打成有序序列）
void InOrder(BinTree T)
{
// 空树返回
    if (T == NULL)
    {
        return;
    }
// 左
    InOrder(T->left);
// 根
    printf("%d ", T->data);
// 右
    InOrder(T->right);
}


// 后序释放整棵树
void FreeTree(BinTree T)
{
// 空树返回
    if (T == NULL)
    {
        return;
    }
// 先孩子
    FreeTree(T->left);
    FreeTree(T->right);
// 后自己
    free(T);
}


// 主函数
int main(void)
{
// 树根，空树从 NULL 开始
    BinTree T = NULL;
// 插入序列
    static const int ins[] = { 8, 3, 10, 1, 6, 14, 4, 7, 13 };
// 计数
    int i;
// 查找结果
    BinTree found;

// 逐个插入
    for (i = 0; i < (int)(sizeof(ins) / sizeof(ins[0])); i++)
    {
        T = BSTInsert(T, ins[i]);
    }

// 用中序验证：必须递增
    printf("插入 %d 个值后，中序遍历: ", (int)(sizeof(ins) / sizeof(ins[0])));
    InOrder(T);
    printf("\n（BST 的中序一定递增 —— 只要有序就说明结构是对的）\n\n");

// 查找命中
    found = BSTFind(T, 7);
    printf("查 7  → %s\n", found ? "找到" : "没找到");
// 查找未命中
    found = BSTFind(T, 99);
    printf("查 99 → %s\n", found ? "找到" : "没找到（BST 里没有）");

// 找最值
    printf("最小值 = %d，最大值 = %d\n\n", FindMin(T)->data, FindMax(T)->data);

// 情况一：删叶子
    T = BSTDelete(T, 7);
    printf("删 7 （叶子）     : ");
    InOrder(T);
    printf("\n");

// 情况二：删只有一个孩子的结点（13 只有左孩子 11？这里删 1 是叶子）
    T = BSTInsert(T, 15);
    T = BSTDelete(T, 14);
    printf("删 14（一个孩子） : ");
    InOrder(T);
    printf("\n");

// 情况三：删有两个孩子的结点
    T = BSTDelete(T, 3);
    printf("删 3 （两个孩子） : ");
    InOrder(T);
    printf("\n");

// 删根
    T = BSTDelete(T, 8);
    printf("删 8 （树根）     : ");
    InOrder(T);
    printf("\n");

// 删一个不存在的值：应该什么都不做
    T = BSTDelete(T, 999);
    printf("删 999（不存在）  : ");
    InOrder(T);
    printf("\n（什么都没变 —— 删除不存在的值不应该破坏结构）\n");

// 释放
    FreeTree(T);
// 正常结束
    return 0;
}

